    45→const DB_COLUMNS = Object.values(COLUMN_MAP);
    46→
    47→function toText(val: unknown): string | null {
    48→  if (val === null || val === undefined) return null;
    49→  const s = String(val).trim();
    50→  return s === '' ? null : s;
    51→}
