    53→export async function POST(req: NextRequest): Promise<NextResponse> {
    54→  let formData: FormData;
    55→  try {
    56→    formData = await req.formData();
    57→  } catch {
    58→    return NextResponse.json({ error: '요청 파싱 실패' }, { status: 400 });
    59→  }
    60→
    61→  const file = formData.get('file') as File | null;
    62→  if (!file) {
    63→    return NextResponse.json({ error: '파일이 없습니다' }, { status: 400 });
    64→  }
    65→
    66→  if (file.size > 10 * 1024 * 1024) {
    67→    return NextResponse.json({ error: '파일 크기가 10MB를 초과합니다' }, { status: 400 });
    68→  }
    69→
    70→  // 확장자 AND MIME 검증 (둘 다 만족해야 통과 — 우회 방지)
    71→  const isXlsx =
    72→    file.name.toLowerCase().endsWith('.xlsx') &&
    73→    file.type === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
    74→  if (!isXlsx) {
    75→    return NextResponse.json({ error: '.xlsx 파일만 업로드 가능합니다' }, { status: 400 });
    76→  }
    77→
    78→  try {
    79→    const buffer = Buffer.from(await file.arrayBuffer());
    80→    const wb = XLSX.read(buffer, { type: 'buffer' });
    81→    const ws = wb.Sheets[wb.SheetNames[0]];
    82→    const rawRows = XLSX.utils.sheet_to_json<Record<string, unknown>>(ws, { defval: null });
    83→
    84→    if (rawRows.length > 0) {
    85→      const headers = Object.keys(rawRows[0]);
    86→      if (!headers.includes('소속대학') || !headers.includes('구분')) {
    87→        return NextResponse.json(
    88→          { error: '필수 컬럼(소속대학, 구분)이 없습니다. RAW 데이터 형식의 파일을 업로드하세요.' },
    89→          { status: 400 }
    90→        );
    91→      }
    92→    }
    93→
    94→    // 매핑 + 중복 제거 (college, department 기준)
    95→    const seen = new Set<string>();
    96→    const rows: Record<string, string | null>[] = [];
    97→    for (const raw of rawRows) {
    98→      const row: Record<string, string | null> = {};
    99→      for (const [excelHeader, dbCol] of Object.entries(COLUMN_MAP)) {
   100→        row[dbCol] = toText(raw[excelHeader]);
   101→      }
   102→      // department fallback
   103→      if (!row['department']) {
   104→        row['department'] = toText(raw['학과명']);
   105→      }
   106→      const key = `${row['college']}||${row['department']}`;
   107→      if (!seen.has(key)) {
   108→        seen.add(key);
   109→        rows.push(row);
   110→      }
   111→    }
   112→
   113→    const db = getDb();
   114→    const insertCols = DB_COLUMNS.join(', ');
   115→    const placeholders = DB_COLUMNS.map(() => '?').join(', ');
   116→    const insertStmt = db.prepare(
   117→      `INSERT INTO to_haejung (${insertCols}) VALUES (${placeholders})`
   118→    );
   119→
   120→    const replaceAll = db.transaction(() => {
   121→      db.prepare('DELETE FROM to_haejung').run();
   122→      for (const row of rows) {
   123→        const values = DB_COLUMNS.map((col) => row[col] ?? null);
   124→        insertStmt.run(values);
   125→      }
   126→    });
   127→    replaceAll();
   128→
   129→    return NextResponse.json({ ok: true, count: rows.length });
   130→  } catch (err) {
   131→    return NextResponse.json(
   132→      { error: err instanceof Error ? err.message : '처리 실패' },
   133→      { status: 500 }
   134→    );
   135→  }
   136→}
