    46→  const blob = new Blob([fileBuffer], { type: mimeType });
    47→  formData.append('file', blob, filename);
    48→  return new NextRequest('http://localhost/api/to-haejung/upload', {
    49→    method: 'POST',
    50→    body: formData,
    51→  });
    52→}
